    Ꮡp.Set(NewP384Point());
    nint tableIndex = 96 - 1;
    foreach (var (_, @byte) in scalar) {
        var windowValue = (byte)((@byte >> (int)(4)));
        tables.Value[tableIndex].Select(t, windowValue);
        Ꮡp.Add(Ꮡp, t);
        tableIndex--;
        windowValue = (byte)(@byte & 0b1111);
        tables.Value[tableIndex].Select(t, windowValue);
        Ꮡp.Add(Ꮡp, t);
        tableIndex--;
    }
    return (Ꮡp, default!);
}

// p384Sqrt sets e to a square root of x. If x is not a square, p384Sqrt returns
// false and e is unchanged. e and x can overlap.
internal static bool /*isSquare*/ p384Sqrt(ж<fiat.P384Element> Ꮡe, ж<fiat.P384Element> Ꮡx) {
    var candidate = @new<fiat.P384Element>();
    p384SqrtCandidate(candidate, Ꮡx);
    var square = @new<fiat.P384Element>().Square(candidate);
    if (square.Equal(Ꮡx) != 1) {
        return false;
    }
    Ꮡe.Set(candidate);
    return true;
}

// p384SqrtCandidate sets z to a square root candidate for x. z and x must not overlap.
internal static void p384SqrtCandidate(ж<fiat.P384Element> Ꮡz, ж<fiat.P384Element> Ꮡx) {
    // Since p = 3 mod 4, exponentiation by (p + 1) / 4 yields a square root candidate.
    //
    // The sequence of 14 multiplications and 381 squarings is derived from the
    // following addition chain generated with github.com/mmcloughlin/addchain v0.4.0.
    //
    //	_10      = 2*1
    //	_11      = 1 + _10
    //	_110     = 2*_11
    //	_111     = 1 + _110
    //	_111000  = _111 << 3
    //	_111111  = _111 + _111000
    //	_1111110 = 2*_111111
    //	_1111111 = 1 + _1111110
    //	x12      = _1111110 << 5 + _111111
    //	x24      = x12 << 12 + x12
    //	x31      = x24 << 7 + _1111111
    //	x32      = 2*x31 + 1
    //	x63      = x32 << 31 + x31
    //	x126     = x63 << 63 + x63
    //	x252     = x126 << 126 + x126
    //	x255     = x252 << 3 + _111
    //	return     ((x255 << 33 + x32) << 64 + 1) << 30
    //
    ж<fiat.P384Element> t0 = @new<fiat.P384Element>();
    ж<fiat.P384Element> t1 = @new<fiat.P384Element>();
    ж<fiat.P384Element> t2 = @new<fiat.P384Element>();
    Ꮡz.Square(Ꮡx);
    Ꮡz.Mul(Ꮡx, Ꮡz);
    Ꮡz.Square(Ꮡz);
    t0.Mul(Ꮡx, Ꮡz);
    Ꮡz.Square(t0);
    for (nint s = 1; s < 3; s++) {
        Ꮡz.Square(Ꮡz);
    }
    t1.Mul(t0, Ꮡz);
    t2.Square(t1);
    Ꮡz.Mul(Ꮡx, t2);
    for (nint s = 0; s < 5; s++) {
        t2.Square(t2);
    }
    t1.Mul(t1, t2);
    t2.Square(t1);
    for (nint s = 1; s < 12; s++) {
        t2.Square(t2);
    }
    t1.Mul(t1, t2);
    for (nint s = 0; s < 7; s++) {
        t1.Square(t1);
    }
    t1.Mul(Ꮡz, t1);
    Ꮡz.Square(t1);
    Ꮡz.Mul(Ꮡx, Ꮡz);
    t2.Square(Ꮡz);
    for (nint s = 1; s < 31; s++) {
        t2.Square(t2);
    }
    t1.Mul(t1, t2);
    t2.Square(t1);
    for (nint s = 1; s < 63; s++) {
        t2.Square(t2);
    }
    t1.Mul(t1, t2);
    t2.Square(t1);
    for (nint s = 1; s < 126; s++) {
        t2.Square(t2);
    }
    t1.Mul(t1, t2);
    for (nint s = 0; s < 3; s++) {
        t1.Square(t1);
    }
    t0.Mul(t0, t1);
    for (nint s = 0; s < 33; s++) {
        t0.Square(t0);
    }
    Ꮡz.Mul(Ꮡz, t0);
    for (nint s = 0; s < 64; s++) {
        Ꮡz.Square(Ꮡz);
    }
    Ꮡz.Mul(Ꮡx, Ꮡz);
    for (nint s = 0; s < 30; s++) {
        Ꮡz.Square(Ꮡz);
    }
}

} // end nistec_package
